test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 10, unitPrice: 8500 };
  assert.equal(lineTotal(line), 85000);
});

test('lineTotal works with single quantity', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 50 };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 85000, total: 85000 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 20, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 5 * 8500 + 20 * 9500 + 1 * 120000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000 }],
  };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals works with an invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expected = 5 * 8500 + 10 * 9500;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[0].sku, 'DES-HOUR');
  assert.equal(addResult.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(addResult.value.lines[1].qty, 10);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DES-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 15);
});

test('addLine enriches new lines with product data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(addResult.ok, true);
  const newLine = addResult.value.lines[1];
  assert.equal(newLine.name, 'Logo package');
  assert.equal(newLine.unitPrice, 120000);
  assert.equal(newLine.vatRate, 21);
});

test('addLine rejects invalid quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 5.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects draft status requirement', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const originalLength = result.value.lines.length;
  addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(result.value.lines.length, originalLength);
});

test('removeLine removes a line from an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
